// The new notebook wizard: pick a template, answer a few questions, check the cells it will write,
// and open the notebook. The engine writes the cells from fixed templates (wizard.py); nothing is
// generated by AI. It also saves the notebook's proof contract (the columns that identify a row of
// the table it writes), which the Prove panel starts from.

const wizardState = { step: 1, template: null, values: {}, preview: null, problem: "", templates: null, group: "all", search: "" };

async function openWizard() {
  if (state.notebook?.dirty && !(await saveNotebook())) return;
  const t = await attempt(() => rpc("wizard_templates"), "Could not open the wizard");
  if (!t) return;
  // An engine from an older build lists templates without the gallery's groups and choices.
  if (!t.groups || !t.choices || !t.multiline) {
    toast("The local engine is older than this app, so it can't list the templates. Restart KratosForge to update it.", true);
    return;
  }
  Object.assign(wizardState, { step: 1, template: null, values: {}, preview: null, problem: "", templates: t, group: "all", search: "",
    lakehouse: state.notebook?.lakehouse || null, name: "" });
  drawWizard();
}

function drawWizard() {
  const w = wizardState;
  const steps = ["Template", "Inputs and output", "Review"];
  const nav = h("ol", { class: "wizard-steps", "aria-label": "Steps" }, steps.map((s, i) =>
    h("li", { class: i + 1 < w.step ? "done" : i + 1 === w.step ? "now" : null, "aria-current": i + 1 === w.step ? "step" : null }, `${i + 1}. ${s}`)));
  const body = h("div", { class: "wizard-body" }, w.step === 1 ? wizardTemplates() : w.step === 2 ? wizardAnswers() : wizardReview(),
    w.problem ? h("p", { class: "field-error" }, w.problem) : null);
  const actions = [btn("Cancel", null, closeDialog, "tool outline")];
  if (w.step > 1) actions.push(btn("Back", null, () => { w.step -= 1; w.problem = ""; drawWizard(); }, "tool outline"));
  if (w.step === 2) actions.push(btn("Next: review", null, wizardToReview, "tool primary"));
  if (w.step === 3) actions.push(btn("Create notebook", "notebook", wizardCreate, "tool primary"));
  const overlay = showDialog("New notebook from a template", h("div", { class: "wizard" }, nav, body), actions);
  overlay.querySelector(".dialog").classList.add("wide");
  const head = overlay.querySelector(".dialog-head");
  head.insertBefore(previewTag(), head.lastChild);
}

// Templates in the chosen group whose title or description has every word of the search.
function wizardShown(templates, group, search) {
  const words = search.toLowerCase().split(/\s+/).filter(Boolean);
  return templates.filter((t) => (group === "all" || t.group === group)
    && words.every((w) => `${t.title} ${t.text}`.toLowerCase().includes(w)));
}

function wizardTemplates() {
  const w = wizardState;
  const all = w.templates.templates;
  const groups = [["all", "All templates"], ...Object.entries(w.templates.groups)];
  const cards = h("div", { class: "wizard-templates" });
  const drawCards = () => {
    const shown = wizardShown(all, w.group, w.search);
    cards.replaceChildren(...(shown.length ? shown.map((t) => h("button", { class: "wizard-template",
      onclick: () => {
        // The same template again (after Back) keeps what was typed; another one starts from its defaults.
        if (w.template?.id !== t.id) {
          w.values = Object.fromEntries(t.fields.filter((f) => w.templates.choices[f]).map((f) => [f, w.templates.choices[f][0][0]]));
        }
        w.template = t; w.step = 2; w.problem = ""; drawWizard();
      } },
    h("b", {}, t.title), h("span", { class: "muted small" }, t.text))) : [h("p", { class: "muted" }, "No template matches.")]));
  };
  drawCards();
  const nav = h("div", { class: "wizard-groups", role: "group", "aria-label": "Template groups" }, groups.map(([id, label]) =>
    h("button", { class: `tool${w.group === id ? " on" : ""}`, "aria-pressed": String(w.group === id),
      onclick: () => { w.group = id; drawWizard(); } },
    label, h("span", { class: "muted small" }, ` ${id === "all" ? all.length : all.filter((t) => t.group === id).length}`))));
  return [h("p", { class: "dialog-text" }, "Each template writes plain cells that read and write through the lakehouse module, so the notebook runs on this PC and in Fabric, and can be proven."),
    nav,
    h("label", { class: "field" }, "Search templates",
      h("input", { type: "search", value: w.search, placeholder: "watermark, quality, calendar…",
        oninput: (e) => { w.search = e.target.value; drawCards(); } })),
    cards];
}

function wizardAnswers() {
  const w = wizardState;
  const t = w.template;
  const field = (key) => {
    const choices = w.templates.choices[key];
    if (choices) {
      const sel = h("select", { onchange: (e) => { w.values[key] = e.target.value; } },
        choices.map(([value, label]) => h("option", { value, selected: w.values[key] === value }, label)));
      return h("label", { class: "field" }, w.templates.fields[key], sel);
    }
    const hint = { source: "dbo.orders", other: "silver.orders", join_table: "dbo.customers", join_on: "customer_id",
      group_by: "order_date, region", columns: "order_id, amount", file: "Files/raw/orders.csv", folder: "Files/raw/orders",
      watermark: "modified_at", dates: "order_date", numbers: "amount", required: "customer_id, order_date",
      allowed: "status: open|closed", ranges: "amount: 0..1000000", rejects: "silver.orders_rejects",
      start: "2020-01-01", end: "2030-12-31", sums: "amount", notebooks: "Load orders\nClean orders", tracked: "city, segment",
      json_file: "Files/raw/orders.json", order_by: "modified_at",
      keys: "order_id", output: "silver.orders" }[key] || "";
    const input = w.templates.multiline.includes(key)
      ? h("textarea", { rows: 3, placeholder: hint, oninput: (e) => { w.values[key] = e.target.value; } }, w.values[key] || "")
      : h("input", { value: w.values[key] || "", placeholder: hint, oninput: (e) => { w.values[key] = e.target.value; } });
    return h("label", { class: "field" }, w.templates.fields[key], input);
  };
  const name = h("input", { value: w.name, placeholder: "Notebook 1", oninput: (e) => { w.name = e.target.value; } });
  const writes = t.fields.includes("output");
  return [h("p", { class: "dialog-text" }, h("b", {}, t.title), `: ${t.text}`),
    h("div", { class: "wizard-fields" }, t.fields.map(field),
      writes ? h("label", { class: "field" }, "Columns to ignore when a proof compares runs",
        h("input", { value: w.values.ignore || "", placeholder: "loaded_at", oninput: (e) => { w.values.ignore = e.target.value; } })) : null,
      h("label", { class: "field" }, "Notebook name", name)),
    h("p", { class: "muted small" }, w.lakehouse
      ? `Attached to ${w.lakehouse.name}. Table names are checked when the notebook runs.`
      : "No lakehouse yet: attach one with Add data items once the notebook opens. Table names are checked when it runs.")];
}

async function wizardToReview() {
  const w = wizardState;
  try {
    w.preview = await rpc("wizard_preview", { template: w.template.id, values: w.values });
    w.problem = "";
    w.step = 3;
  } catch (e) {
    w.problem = friendlyError(e).text;
  }
  drawWizard();
}

// What the review step says about the proof contract: the columns that match rows of each table it writes.
function wizardContract(tables) {
  const entries = Object.entries(tables);
  if (!entries.length) return "This notebook writes no tables, so there is no proof contract.";
  return `Proof contract saved in the notebook: ${entries.map(([table, rules]) =>
    `rows of ${table} are ${rules.keys.length ? `matched by ${rules.keys.join(", ")}` : "compared whole"}`
    + (rules.ignore.length ? `, ignoring ${rules.ignore.join(", ")}` : "")).join("; ")}.`;
}

function wizardReview() {
  const p = wizardState.preview;
  return [h("p", { class: "dialog-text" }, "The notebook will have these cells. Change anything once it opens."),
    // Scrolls on its own, so it takes focus for the keyboard to scroll it.
    h("div", { class: "wizard-cells", tabindex: "0", role: "region", "aria-label": "Cells the notebook will have" }, p.cells.map((c) => (c.type === "markdown"
      ? h("div", { class: "wizard-md" }, c.source.split("\n")[0].replace(/^#\s*/, ""))
      : h("pre", { class: "mono" }, c.source)))),
    h("p", { class: "muted small" }, wizardContract(p.proof.tables))];
}

async function wizardCreate() {
  const w = wizardState;
  try {
    const nb = await rpc("wizard_create", { template: w.template.id, values: w.values, lakehouse_ref: w.lakehouse, name: w.name.trim() || null });
    closeDialog();
    loadIntoState(nb);
    go("notebook");
    toast(`Created ${nb.name}. Run it here, or open Prove to run it on this PC and in Fabric and compare.`);
  } catch (e) {
    w.problem = friendlyError(e).text;
    drawWizard();
  }
}

registerFeature({
  id: "wizard", preview: true,
  commands: [{ label: "New notebook from a template", icon: "notebook", keywords: "wizard template create notebook clean join load file folder incremental watermark standardize quality rejects scd date calendar dimension reconcile orchestrate run", run: openWizard }],
});
